import{_ as p,C as d,o as c,c as u,a6 as l,j as t,a,E as i,w as n}from"./chunks/framework.BgIEWZ8W.js";const k=JSON.parse('{"title":"File Upload · Case File (Mental Model)","description":"Extension parsing, content-type trust, polyglots, path traversal in filenames, and race-condition uploads explained like a detective investigation.","frontmatter":{"title":"File Upload · Case File (Mental Model)","description":"Extension parsing, content-type trust, polyglots, path traversal in filenames, and race-condition uploads explained like a detective investigation."},"headers":[],"relativePath":"file-upload/index.md","filePath":"file-upload/index.md"}'),h={name:"file-upload/index.md"},g={tabindex:"0"};function m(f,e,v,b,w,y){const o=d("Term"),s=d("LabGroup"),r=d("TopicComplete");return c(),u("div",null,[e[26]||(e[26]=l('<h1 id="file-upload-vulnerabilities-·-the-core-investigation" tabindex="-1">File Upload Vulnerabilities · The Core Investigation <a class="header-anchor" href="#file-upload-vulnerabilities-·-the-core-investigation" aria-label="Permalink to &quot;File Upload Vulnerabilities · The Core Investigation&quot;">​</a></h1><p class="wd-section-lede">An upload form is an open invitation for visitors to write raw bytes directly onto the server&#39;s hard drive. The vulnerability happens when the server decides what a file <em>is</em> based on labels the user controls, stores it inside an executable folder, and then asks an execution engine to run it.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Trophy with a Secret Engine.</strong> Imagine a community center that allows visitors to donate trophies for display in the glass foyer. If a visitor brings in a wooden trophy labeled <em>&quot;Harmless Statue&quot;</em>, but secretly hollows out the base and installs an active remote-control engine, placing it in the foyer gives the visitor control over the room. Real security means checking the physical material (not just the shipping label), stripping active mechanisms, and placing it in a separate, non-conductive storage room.</p></div><h2 id="case-file-1-following-an-uploaded-file-behind-the-curtain" tabindex="-1">Case File #1: Following an Uploaded File Behind the Curtain <a class="header-anchor" href="#case-file-1-following-an-uploaded-file-behind-the-curtain" aria-label="Permalink to &quot;Case File #1: Following an Uploaded File Behind the Curtain&quot;">​</a></h2><p>Let&#39;s trace what happens when you update your profile avatar on a web application.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You click &quot;Change Avatar&quot;, select an image on your computer, and press &quot;Upload&quot;. Your browser packages the image into a <code>multipart/form-data</code> HTTP request with a <code>filename=&quot;avatar.png&quot;</code> attribute and a <code>Content-Type: image/png</code> header, then posts it to <code>/my-account/avatar</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The server receives the byte stream, extracts the filename and header, checks if the extension is acceptable, and writes the bytes into a publicly accessible folder like <code>/var/www/html/avatars/avatar.png</code> so that the browser can display it later.</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Server Storage Path</span><span><span class="wd-code-input">Gold</span> = Client-Provided Filename</span></div><span class="wd-code-dev">/var/www/html/avatars/</span><span class="wd-code-input">avatar.png</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The client completely controls the filename and the <code>Content-Type</code> header. If a user uploads a server-side script (such as a PHP or ASP file), and the server stores it inside the web root where script execution is enabled, visiting the file&#39;s URL causes the web server&#39;s runtime interpreter to execute the file instead of merely serving it as static image bytes.</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers isolate uploads outside the public web root, generate random alphanumeric filenames (e.g., UUIDs) rather than trusting client filenames, re-encode uploaded images through an image processing library, and disable script execution permissions on storage folders.</p></div></div><h3 id="visual-comparison-trusted-label-vs-actual-bytes" tabindex="-1">Visual Comparison: Trusted Label vs. Actual Bytes <a class="header-anchor" href="#visual-comparison-trusted-label-vs-actual-bytes" aria-label="Permalink to &quot;Visual Comparison: Trusted Label vs. Actual Bytes&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer believed checking <code>Content-Type: image/png</code> in the incoming HTTP header guaranteed that only legitimate graphic image files would be saved into the avatar directory.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>HTTP headers are authored entirely by the client. An intercepting proxy allowed sending a script file named <code>shell.php</code> while keeping <code>Content-Type: image/png</code>, tricking the server into saving executable code into a web-served folder.</p></div></div><h3 id="how-an-http-multipart-request-labels-uploaded-data" tabindex="-1">How an HTTP Multipart Request Labels Uploaded Data <a class="header-anchor" href="#how-an-http-multipart-request-labels-uploaded-data" aria-label="Permalink to &quot;How an HTTP Multipart Request Labels Uploaded Data&quot;">​</a></h3><p>Here is how an upload request splits metadata from file contents in an HTTP POST:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Multipart Envelope</span><span><span class="wd-code-input">Gold</span> = Client-Controlled Filename &amp; Header</span></div><span class="wd-code-dev">Content-Disposition: form-data; name=&quot;avatar&quot;; </span><span class="wd-code-input">filename=&quot;exploit.php&quot;</span><br><span class="wd-code-dev">Content-Type: </span><span class="wd-code-input">image/jpeg</span><br><br><span class="wd-code-input">&lt;?php echo file_get_contents(&#39;/etc/passwd&#39;); ?&gt;</span></div><hr><h2 id="the-4-stage-lifecycle-of-every-uploaded-file" tabindex="-1">The 4-Stage Lifecycle of Every Uploaded File <a class="header-anchor" href="#the-4-stage-lifecycle-of-every-uploaded-file" aria-label="Permalink to &quot;The 4-Stage Lifecycle of Every Uploaded File&quot;">​</a></h2><p>To understand where an upload vulnerability lurks, trace the file across its four critical checkpoints:</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>1. Client Submission</strong> Browser sends file bytes, original filename, and declared MIME header. (Untrusted input originates here!) </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Server Validation</strong> App checks extension, MIME header, or magic bytes against its validation policy. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>3. Filesystem Placement</strong> App writes file to disk (either inside web root or in a private, isolated storage bucket). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Retrieval &amp; Execution</strong> User requests the URL. Does the server treat it as static text or feed it to a script engine? </div></div><hr><h2 id="what-the-server-checks-vs-what-the-client-controls" tabindex="-1">What the Server Checks vs. What the Client Controls <a class="header-anchor" href="#what-the-server-checks-vs-what-the-client-controls" aria-label="Permalink to &quot;What the Server Checks vs. What the Client Controls&quot;">​</a></h2><p>Defenses fail when they inspect only what the user claims rather than how the file is stored and parsed:</p>',18)),t("table",g,[e[15]||(e[15]=t("thead",null,[t("tr",null,[t("th",null,"Validation Check"),t("th",null,"What the Client Controls"),t("th",null,"How the Check Breaks")])],-1)),t("tbody",null,[e[11]||(e[11]=t("tr",null,[t("td",null,[t("code",null,"Content-Type"),a(" header")]),t("td",null,"Fully controlled by client"),t("td",null,[a("The client simply forges "),t("code",null,"image/jpeg"),a(" while uploading a script.")])],-1)),e[12]||(e[12]=t("tr",null,[t("td",null,"Filename extension"),t("td",null,"Fully controlled by client"),t("td",null,[a("Blocklist misses alternatives like "),t("code",null,".phtml"),a(", "),t("code",null,".php5"),a(", or "),t("code",null,".phar"),a(".")])],-1)),t("tr",null,[e[3]||(e[3]=t("td",null,"Magic bytes (file signature)",-1)),e[4]||(e[4]=t("td",null,"First few bytes controlled",-1)),t("td",null,[e[1]||(e[1]=a("A ",-1)),i(o,{id:"mime-polyglot"},{default:n(()=>[...e[0]||(e[0]=[a("polyglot",-1)])]),_:1}),e[2]||(e[2]=a(" combines valid image headers with script code.",-1))])]),e[13]||(e[13]=t("tr",null,[t("td",null,"Image re-encoding"),t("td",null,"Re-encoded output"),t("td",null,"Skipped entirely, or only resized without stripping metadata tags.")],-1)),t("tr",null,[e[9]||(e[9]=t("td",null,"Destination path",-1)),e[10]||(e[10]=t("td",null,"Filename path components",-1)),t("td",null,[i(o,{id:"canonicalization"},{default:n(()=>[...e[5]||(e[5]=[a("Path traversal",-1)])]),_:1}),e[6]||(e[6]=a(" (",-1)),e[7]||(e[7]=t("code",null,"../../",-1)),e[8]||(e[8]=a(") writes outside the upload folder into executable roots.",-1))])]),e[14]||(e[14]=t("tr",null,[t("td",null,"Web directory execution"),t("td",null,"Server configuration"),t("td",null,"The upload folder has execution handlers enabled (e.g., PHP-FPM / CGI).")],-1))])]),e[27]||(e[27]=l('<details class="details custom-block"><summary>🔬 Under the Hood: Why Web Servers Handle Filenames Differently</summary><p>Filename parsing differences between web servers and operating systems often create unexpected execution paths:</p><ul><li><strong>Apache <code>mod_mime</code> and MultiViews:</strong> Apache can evaluate extensions from right to left or across multiple dots. If configured with handler mapping, a file named <code>exploit.php.jpg</code> may be executed as PHP if the server maps <code>.php</code> to the PHP handler regardless of trailing extensions.</li><li><strong>IIS Semicolon Parsing:</strong> Historically, older IIS servers truncated filenames at semicolons (<code>exploit.asp;.jpg</code>), passing <code>exploit.asp</code> to the ASP handler while the validator only verified the trailing <code>.jpg</code>.</li><li><strong>Nginx <code>cgi.fix_pathinfo=1</code>:</strong> If Nginx is paired with PHP-FPM with <code>cgi.fix_pathinfo</code> enabled, requesting <code>/uploads/photo.jpg/test.php</code> causes PHP to look for <code>test.php</code>, fail, and walk back up the path to execute <code>photo.jpg</code> as PHP.</li></ul></details><details class="details custom-block"><summary>⚙️ Engine Variations: Executable Extensions by Stack</summary><p>Different application runtimes look for different file extensions:</p><ul><li><strong>PHP:</strong> <code>.php</code>, <code>.php3</code>, <code>.php4</code>, <code>.php5</code>, <code>.phtml</code>, <code>.phar</code> (which can trigger object deserialization on file operations).</li><li><strong>ASP.NET:</strong> <code>.aspx</code>, <code>.ashx</code>, <code>.asmx</code>, <code>.config</code> (uploading a custom <code>web.config</code> can enable script execution in that folder).</li><li><strong>Java:</strong> <code>.jsp</code>, <code>.jspx</code>, <code>.war</code> (if the application server auto-deploys WAR archives).</li><li><strong>Node.js:</strong> Node does not execute files based on extensions by default; risks arise when uploaded templates or JavaScript modules are dynamically imported or rendered by a template engine.</li><li><strong>Python:</strong> <code>.py</code> files do not execute automatically unless dynamically imported or evaluated by the app.</li></ul></details><hr><h2 id="practice-labs-the-5-investigation-angles" tabindex="-1">Practice Labs: The 5 Investigation Angles <a class="header-anchor" href="#practice-labs-the-5-investigation-angles" aria-label="Permalink to &quot;Practice Labs: The 5 Investigation Angles&quot;">​</a></h2><p>Put these concepts into practice across the 5 common upload scenarios:</p><h3 id="_1-direct-script-uploads-content-type-bypass" tabindex="-1">1. Direct Script Uploads &amp; Content-Type Bypass <a class="header-anchor" href="#_1-direct-script-uploads-content-type-bypass" aria-label="Permalink to &quot;1. Direct Script Uploads &amp; Content-Type Bypass&quot;">​</a></h3><p>When an upload directory is located directly inside the public web root and has execution permissions enabled, uploading a minimal script file gives immediate code execution. When the server validates only the <code>Content-Type</code> header, changing that header in your intercepting proxy allows the file through.</p>',7)),i(s,{ids:"file-upload-lab-file-upload-remote-code-execution-via-web-shell-upload, file-upload-lab-file-upload-web-shell-upload-via-content-type-restriction-bypass"}),e[28]||(e[28]=t("h3",{id:"_2-path-traversal-filename-manipulation",tabindex:"-1"},[a("2. Path Traversal & Filename Manipulation "),t("a",{class:"header-anchor",href:"#_2-path-traversal-filename-manipulation","aria-label":'Permalink to "2. Path Traversal & Filename Manipulation"'},"​")],-1)),e[29]||(e[29]=t("p",null,[a("When the upload folder forbids execution, attackers look for ways to store the file somewhere else. If the server takes the client-supplied filename and concatenates it directly into the save path without sanitization, path traversal sequences ("),t("code",null,"../"),a(" or "),t("code",null,"..%2f"),a(") can write the file into a parent folder that "),t("em",null,"does"),a(" execute scripts.")],-1)),i(s,{ids:"file-upload-lab-file-upload-web-shell-upload-via-path-traversal, file-upload-lab-file-upload-web-shell-upload-via-extension-blacklist-bypass, file-upload-lab-file-upload-web-shell-upload-via-obfuscated-file-extension"}),e[30]||(e[30]=l('<details class="details custom-block"><summary>💡 Detective Tip: Bypassing Blocklists with Configuration Files</summary><p>If an application blocks <code>.php</code> extensions, developers may still have forgotten to block server configuration files. On Apache servers, uploading a custom <code>.htaccess</code> file can map an otherwise harmless extension (like <code>.l33t</code> or <code>.png</code>) to the PHP handler:</p><div class="language-apache vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">apache</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AddType</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> application/x-httpd-php</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .l33t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Once that <code>.htaccess</code> is uploaded into the folder, uploading <code>exploit.l33t</code> will execute as live PHP!</p></details><h3 id="_3-content-validation-polyglot-files" tabindex="-1">3. Content Validation &amp; Polyglot Files <a class="header-anchor" href="#_3-content-validation-polyglot-files" aria-label="Permalink to &quot;3. Content Validation &amp; Polyglot Files&quot;">​</a></h3>',2)),t("p",null,[e[17]||(e[17]=a("When a server verifies that a file is truly an image by checking its initial magic bytes (such as ",-1)),e[18]||(e[18]=t("code",null,"GIF89a;",-1)),e[19]||(e[19]=a(" or the JPEG SOI marker ",-1)),e[20]||(e[20]=t("code",null,"FF D8 FF",-1)),e[21]||(e[21]=a("), simple text scripts will be rejected. A ",-1)),i(o,{id:"mime-polyglot"},{default:n(()=>[...e[16]||(e[16]=[a("polyglot",-1)])]),_:1}),e[22]||(e[22]=a(" file satisfies both formats: it contains valid image metadata headers so image parsers accept it, while containing executable script code inside an image comment or metadata field.",-1))]),i(s,{ids:"file-upload-lab-file-upload-remote-code-execution-via-polyglot-web-shell-upload"}),e[31]||(e[31]=t("h3",{id:"_4-non-atomic-uploads-race-conditions",tabindex:"-1"},[a("4. Non-Atomic Uploads & Race Conditions "),t("a",{class:"header-anchor",href:"#_4-non-atomic-uploads-race-conditions","aria-label":'Permalink to "4. Non-Atomic Uploads & Race Conditions"'},"​")],-1)),t("p",null,[e[24]||(e[24]=a("Many applications save an uploaded file into a temporary directory first, run validation or an antivirus scan, and delete the file if it fails. If that temporary location is web-accessible during the milliseconds before the server unlinks the file, concurrent requests can execute the file inside that tiny ",-1)),i(o,{id:"toctou-race"},{default:n(()=>[...e[23]||(e[23]=[a("TOCTOU race window",-1)])]),_:1}),e[25]||(e[25]=a(".",-1))]),i(s,{ids:"file-upload-lab-file-upload-web-shell-upload-via-race-condition"}),e[32]||(e[32]=l(`<details class="details custom-block"><summary>🔬 Under the Hood: The Race Condition Window</summary><p>A typical non-atomic upload workflow looks like this:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Receive multipart body      → Write /var/www/uploads/temp-9823.php</span></span>
<span class="line"><span>2. Inspect file / scan content  → Determine file is malicious (takes 20ms)</span></span>
<span class="line"><span>3. Unlink / delete file        → rm /var/www/uploads/temp-9823.php</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If an investigator fires hundreds of GET requests for <code>temp-9823.php</code> while the upload is being processed, requests that hit during that 20ms window between Step 1 and Step 3 will successfully execute before the cleanup finishes.</p></details><hr><h2 id="the-detective-s-upload-testing-checklist" tabindex="-1">The Detective&#39;s Upload Testing Checklist <a class="header-anchor" href="#the-detective-s-upload-testing-checklist" aria-label="Permalink to &quot;The Detective&#39;s Upload Testing Checklist&quot;">​</a></h2><p>When investigating an upload form, proceed systematically:</p><ol><li><strong>Test Baseline Upload:</strong> Upload a legitimate image (<code>avatar.png</code>) and observe the response: Where is it saved? What URL does the page use to display it?</li><li><strong>Inspect Content-Type Trust:</strong> Upload a script file while modifying <code>Content-Type</code> to <code>image/png</code>. Does the server accept it?</li><li><strong>Test Extension Variations:</strong> If <code>.php</code> is blocked, test <code>.phtml</code>, <code>.php5</code>, <code>.phar</code>, or configuration files like <code>.htaccess</code>.</li><li><strong>Test Path Traversal:</strong> Supply <code>filename=&quot;../avatar.png&quot;</code> or <code>filename=&quot;..%2favatar.png&quot;</code> to see if the file lands in a parent directory.</li><li><strong>Test Magic Bytes &amp; Polyglots:</strong> Prepend valid file signatures (like <code>GIF89a;</code>) or embed payloads into image EXIF/comment sections.</li><li><strong>Test Concurrency:</strong> If validation deletes files after saving, test for race conditions using parallel requests.</li></ol><hr><h2 id="how-developers-lock-it-down-permanently" tabindex="-1">How Developers Lock It Down Permanently <a class="header-anchor" href="#how-developers-lock-it-down-permanently" aria-label="Permalink to &quot;How Developers Lock It Down Permanently&quot;">​</a></h2><p>Secure file handling requires defense in depth across all four lifecycle stages:</p><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Golden Rules of Secure Uploads:</strong></p><ul><li><strong>Store Outside Web Root:</strong> Store uploaded files in an isolated private directory or cloud storage bucket (e.g., AWS S3, Google Cloud Storage) completely separated from executable code.</li><li><strong>Generate Random Names:</strong> Never use client-supplied filenames on disk. Assign a generated UUID and append an extension determined by the server&#39;s own strict allow-list.</li><li><strong>Re-Encode Media:</strong> Process images through an image processing library (e.g., ImageMagick or Sharp) to strip comments and regenerate pixel data from scratch, neutralizing polyglots.</li><li><strong>Disable Execution:</strong> Configure the web server to disable execution engines (e.g., <code>php_flag engine off</code> or Nginx <code>location ^~ /uploads/ { }</code> with no script handler).</li><li><strong>Safe Download Headers:</strong> Serve user-uploaded downloads with <code>Content-Disposition: attachment</code> and <code>X-Content-Type-Options: nosniff</code> to prevent browser mime-sniffing execution.</li></ul></div>`,9)),i(r,{"topic-id":"file-upload-vulnerabilities",label:"Mark file upload complete"})])}const T=p(h,[["render",m]]);export{k as __pageData,T as default};
